function parseThresholds(thresholdStrings?: string[]) {
  if (!thresholdStrings || thresholdStrings.length === 0) {
    return { valid: true, thresholds: null, errors: [] };
  }

  const errors = [];
  const thresholds: Record<string, number> = {};

  for (const str of thresholdStrings) {
    const match = str.match(/^([a-z_]+)=([0-9.]+)$/);
    if (!match) {
      errors.push(`Malformed threshold: "${str}" (expected format: metric=min)`);
      continue;
    }

    const [, metricId, minStr] = match;
    const minValue = Number.parseFloat(minStr);

    if (Number.isNaN(minValue) || minValue < 0 || minValue > 1) {
      errors.push(`Invalid threshold value for ${metricId}: ${minStr} (must be a number between 0 and 1)`);
      continue;
    }

    thresholds[metricId] = minValue;
  }

  return {
    valid: errors.length === 0,
    thresholds: Object.keys(thresholds).length > 0 ? thresholds : null,
    errors
  };
}

function runEvalCommand(options: EvalOptions) {
  assertFileExists(options.outputs);

  const thresholdParse = parseThresholds(options.threshold);
  if (!thresholdParse.valid) {
    log.error('Threshold validation failed.');
    thresholdParse.errors.forEach((err) => console.error(` - ${err}`));
    process.exit(2);
  }

  const dataset = (Eval.loadDataset as unknown as (config: unknown) => any)({
    outputsPath: options.outputs,
    referencesPath: options.references
  });
  const evaluations = (Eval.runEvaluations as unknown as (config: unknown) => any)({
    outputs: dataset.outputs,
    references: dataset.references
  });

  let report;
  try {
    report = (Eval.generateReport as unknown as (config: unknown) => any)({
      evaluations,
      outputsPath: dataset.outputsPath,
      referencesPath: dataset.referencesPath,
      thresholds: thresholdParse.thresholds
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    if (message.includes('Invalid thresholds')) {
      log.error('Threshold error.');
      console.error(` - ${message}`);
      process.exit(2);
    }
    throw error;
  }

  const resolvedPath = (Eval.writeReport as unknown as (config: unknown) => string)({
    report,
    format: options.format ?? 'json',
    reportPath: options.report
  });
  log.success('Evaluation report generated.', { path: resolvedPath });

  if (report.passed === false) {
    process.exit(1);
  }
}

