console.log('Test 1 (valid thresholds):', val1.valid === true ? 'PASS' : 'FAIL');

// Test 2: Thresholds pass
const eval2 = impl.evaluateThresholds({ exact_match: 0.9, toxicity: 0.95 }, evals1);
