console.log('Test 3 (thresholds fail):', eval3.passed === false && eval3.thresholds[0].passed === false ? 'PASS' : 'FAIL');

// Test 4: Thresholds fail (score is null)
const evals4 = [
  { id: 'exact_match', score: null }
];
const eval4 = impl.evaluateThresholds({ exact_match: 0.0 }, evals4);
console.log('Test 4 (null score fails):', eval4.passed === false && eval4.thresholds[0].passed === false ? 'PASS' : 'FAIL');

// Test 5: Invalid threshold (unknown metric)
